import {createState,sample,powered,distance,issues,NETS,log,selfTests} from './logic.mjs';
import {Scene,parts} from './scene-three.mjs';
const $=id=>document.getElementById(id);let state=createState(),running=true,speed=1,acc=0,last=performance.now(),demo=null;
const scene=new Scene($('scene'),selectPart);
function time(t){return `${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;}
function selectPart(id){scene.selected=id;const p=parts.find(p=>p.id===id);$('part-name').textContent=p.name;$('part-description').textContent=p.description;$('part-pins').replaceChildren(...p.pins.map(text=>{const e=document.createElement('span');e.className='pins';e.textContent=text;return e;}));document.querySelectorAll('[data-part]').forEach(b=>b.classList.toggle('active',b.dataset.part===id));}
for(const p of parts){const b=document.createElement('button');b.dataset.part=p.id;b.innerHTML=`<i class="swatch" style="background:${p.color}"></i><span>${p.name}</span>`;b.onclick=()=>selectPart(p.id);$('inventory').append(b);}$('part-count').textContent=`${parts.length} ASSEMBLIES`;
for(const [id,name,note] of NETS){const label=document.createElement('label');label.className='net';const input=document.createElement('input');input.type='checkbox';input.checked=true;input.dataset.net=id;input.setAttribute('aria-label',name);const text=document.createElement('div');text.textContent=name;const small=document.createElement('span');small.textContent=note;text.append(small);label.append(input,text);input.onchange=()=>{state.nets[id]=input.checked;state.up=state.down=0;state.valid=false;state.reason='Wiring changed. Take a sample to evaluate.';log(state,`${input.checked?'CONNECTED':'DISCONNECTED'} · ${name}`);render();};$('nets').append(label);}
function setFill(value){state.fill=Number(value);$('fill').value=state.fill;render();}
$('fill').oninput=e=>{stopDemo();setFill(e.target.value);};document.querySelectorAll('[data-fill]').forEach(b=>b.onclick=()=>{stopDemo();setFill(b.dataset.fill);});
$('height').onchange=e=>{const v=Number(e.target.value);if(!Number.isFinite(v)||v<10||v>350){e.target.value=state.height;return;}stopDemo();state.height=v;state.up=state.down=0;state.valid=false;state.reason='Calibration changed. Next sample uses the new depth.';log(state,`SIM calibrated empty depth to ${v} cm.`);render();};
for(const key of ['power','wifi','calibrated','fault','contact'])$(key).onchange=e=>{stopDemo();state[key]=e.target.checked;if(key==='power'||key==='calibrated'||key==='fault'){state.up=state.down=0;state.valid=false;}state.reason='Inputs changed. Take a sample to evaluate.';log(state,`${key.toUpperCase()} ${state[key]?'ON':'OFF'}`);render();};
$('play').onclick=()=>{running=!running;$('play').textContent=running?'Ⅱ Pause':'▶ Resume';};$('speed').onchange=e=>{speed=Number(e.target.value);};$('step').onclick=()=>{tick();acc=0;render();};
function setView(view){scene.view=view;scene.focused=null;scene.zoom=1;scene.yaw=view==='circuit'?-0.1:-.56;scene.pitch=view==='circuit'?.65:.27;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('viewcaption').textContent={product:'01 / ASSEMBLED CONCEPT',exploded:'02 / COMPONENT ASSEMBLY',circuit:'03 / CONNECTION EXPLORER'}[view];$('scene-title').innerHTML={product:'A cleaner future,<br>one smarter bin.',exploded:'Every part.<br>One connected system.',circuit:'Follow the signal.<br>Trace the power.'}[view];}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('cutaway').onclick=()=>{scene.cut=!scene.cut;$('cutaway').classList.toggle('active',scene.cut);$('cutaway').textContent=scene.cut?'Cutaway on':'Cutaway off';};$('wires').onclick=()=>{scene.wires=!scene.wires;$('wires').classList.toggle('active',scene.wires);$('wires').textContent=scene.wires?'Wires on':'Wires off';};$('home').onclick=()=>setView(scene.view);$('focus-part').onclick=()=>{scene.cut=true;$('cutaway').textContent='Cutaway on';$('cutaway').classList.add('active');scene.focus(scene.selected);};
$('restore').onclick=()=>{stopDemo();state.up=state.down=0;state.valid=false;for(const [id] of NETS)state.nets[id]=true;document.querySelectorAll('[data-net]').forEach(e=>e.checked=true);log(state,'All modeled connections restored.');state.reason='Wiring restored. Take a sample to evaluate.';render();};$('clear').onclick=()=>{state.events=[];render();};
$('test').onclick=()=>{const results=selfTests();$('test-results').replaceChildren(...results.map(r=>{const p=document.createElement('div');p.textContent=`${r.pass?'✓':'✕'} ${r.name}`;p.style.color=r.pass?'#bcf394':'#ff9977';return p;}));};
function stopDemo(){if(demo){demo=null;$('demo').textContent='▶ Play working demo';}}
$('demo').onclick=()=>{if(demo){stopDemo();return;}acc=0;state=createState();state.fill=35;demo={start:state.time};running=true;speed=5;$('speed').value='5';$('play').textContent='Ⅱ Pause';for(const k of ['power','wifi','calibrated','contact'])$(k).checked=true;$('fault').checked=false;document.querySelectorAll('[data-net]').forEach(e=>e.checked=true);$('height').value=50;setView('product');log(state,'DEMO · fill, confirm high alert, lose Wi-Fi, empty, reconnect.');$('demo').textContent='■ Stop working demo';render();};
function tick(){if(demo){const elapsed=state.time-demo.start;if(elapsed<5)state.fill=35;else if(elapsed<25)state.fill=85;else if(elapsed<30){state.wifi=false;$('wifi').checked=false;}else if(elapsed<50)state.fill=10;else{state.wifi=true;$('wifi').checked=true;}if(elapsed>=55){log(state,'DEMO COMPLETE · normal → critical → offline reset → reconnect.');stopDemo();running=false;$('play').textContent='▶ Resume';}}sample(state);}
function render(){const live=powered(state),d=distance(state);scene.fill=state.fill/100;scene.led=live&&state.critical&&state.nets.led;scene.power=live;scene.nets=state.nets;$('fill').value=state.fill;$('fill-label').textContent=`${state.fill}%`;$('metric-fill').innerHTML=`${state.fill}<small>%</small>`;$('metric-distance').innerHTML=`${d.toFixed(1)}<small>cm</small>`;$('metric-time').textContent=time(state.time);$('metric-state').textContent=!live?'OFF':!state.calibrated?'UNCALIBRATED':state.critical?'CRITICAL':'NORMAL';$('metric-state').className=state.critical&&live?'critical':'normal';$('status').textContent=state.reason;$('status').classList.toggle('warn',!live||!state.calibrated||state.fault||state.critical||!state.valid&&state.time>0);const count=state.critical?state.down:state.up;$('confirm').textContent=`${count} / 3`;$('confirmbar').style.width=`${count/3*100}%`;$('led').textContent=scene.led?'ON':'OFF';$('buzzer').textContent=live&&state.critical&&state.nets.buzzer?'PULSING':'OFF';$('cloud').textContent=!live?'OFF':state.wifi?'SIM ONLINE':`OFFLINE (${state.pending.length})`;const problems=issues(state);$('electrical').textContent=problems.length?problems.join(' · '):'8 / 8 modeled connections closed. Nominal divider output: 3.33 V.';$('electrical').classList.toggle('warn',!!problems.length);$('events').replaceChildren(...state.events.map(e=>{const div=document.createElement('div');div.className='event';const t=document.createElement('time');t.textContent=time(e.time);const b=document.createElement('b');b.textContent=e.text;div.append(t,b);return div;}));}
log(state,'SIM READY · bin-001 · calibrated depth 50 cm.');selectPart('sensor');render();
function frame(now){const dt=Math.min((now-last)/1000,.3);last=now;if(running){acc+=dt*speed;if(acc>=5){acc-=5;tick();render();}}requestAnimationFrame(frame);}requestAnimationFrame(frame);
// Read-only snapshot for diagnostics and regression verification.
window.swadsSnapshot=()=>JSON.parse(JSON.stringify(state));window.swadsChecks=selfTests;

window.swadsGraphics=()=>scene.diagnostics();
